\chapter{Flattening Stratification of a Coherent Sheaf}
\label{chap:Picard_FlatteningStratification}

\section{Setup and motivation}
\label{sec:flatstrat_setup}

The construction of the Quot scheme \(\Quot_{\F/X/S}^{\Phi,L}\) in Nitsure's exposition
of Grothendieck's existence theorem (\cite{nitsure-hilbert-quot}, \S5) proceeds by
embedding the functor of points of \(\Quot\) into a Grassmannian via Castelnuovo--Mumford
regularity, then cutting out the locus of \emph{quotients with flat fibres of the
prescribed Hilbert polynomial} by a closed-subscheme condition.  Cutting out this
locus uses, as a primary technical input, the existence of the
\emph{flattening stratification} of a coherent sheaf \(\F\) on a projective
\(S\)-scheme: a finite collection of locally-closed subschemes of \(S\) on each of which
the restriction of \(\F\) becomes flat.

We work throughout with a noetherian base scheme \(S\), a projective morphism
\(\pi : X \to S\), and a coherent \(\OO_X\)-module \(\F\). The conclusion of Nitsure's
theorem covers an arbitrary noetherian base with a projective \(X \to S\), which
applies in particular to \(X = C \times_k T\), where \(C\) is a smooth proper
curve over a field \(k\), \(T\) is a noetherian \(k\)-scheme, and \(\F\) is a
coherent sheaf on the relative curve.

\section{Coherent flatness over a base}
\label{sec:coh_flat}

\begin{definition}[Coherent sheaf flat over the base]\leanok
  \label{def:coherent_sheaf_flat}
  \lean{AlgebraicGeometry.Scheme.CoherentSheafFlat}
  Let \(S\) be a noetherian scheme, \(f : X \to S\) a morphism of finite type, and
  \(\F\) a coherent \(\OO_X\)-module.  We say \(\F\) is \emph{flat over \(S\)}
  (equivalently, \(\F\) is \emph{\(f\)-flat}, or \emph{\(S\)-flat}) if for every
  point \(x \in X\) the stalk \(\F_x\) is a flat \(\OO_{S, f(x)}\)-module, where the
  \(\OO_{S, f(x)}\)-module structure is given by the composite
  \(\OO_{S, f(x)} \to \OO_{X, x} \to \End(\F_x)\).
  \textit{Source: cf.\ [Stacks Project], tag 00HB (flat modules); [Nitsure], \S4
  passim.}
  Equivalently (after pulling back to an affine open \(U = \Spec A \subseteq S\) and
  an affine open \(V = \Spec B \subseteq f^{-1}(U)\) with \(\F|_V = \widetilde{M}\)
  for \(M\) a finite \(B\)-module), \(\F|_V\) is \(\OO_U\)-flat in the sense that \(M\) is a
  flat \(A\)-module (with the \(A\)-module structure coming from the ring map
  \(A \to B\)).
\end{definition}

\begin{remark}
\label{rem:coh_flat_pullback}
  The condition is stable under base change: for any morphism \(g : S' \to S\),
  pulling back along the cartesian square
  \[
    \begin{tikzcd}
      X' \ar[r, "g'"] \ar[d, "f'"'] & X \ar[d, "f"] \\
      S' \ar[r, "g"]                & S
    \end{tikzcd}
  \]
  yields a coherent \(\OO_{X'}\)-module \(\F' := (g')^* \F\) which is \(S'\)-flat
  whenever \(\F\) is \(S\)-flat.  Indeed, at each stalk the pullback is an
  extension of scalars of the original flat module, and extension of scalars
  preserves flatness. The converse fails in general.
\end{remark}

  is representable. Then for every \(P\in C(k)\), the scheme \(\Pic^0_{C/k}\)
  satisfies the Albanese universal property for the pointed curve \((C,P)\).
\end{lemma}

\begin{proof}
  \uses{lem:pic0_isAlbanese_algClosed}
  For \(g(C) > 0\) and \(k\) algebraically closed this is
  \cref{lem:pic0_isAlbanese_algClosed}.

  Three extensions are required. Over a general \(k\), apply the algebraically
  closed case over \(k^s\) and descend: the universal morphism and the factoring
  homomorphism are unique, so they are Galois-equivariant and descend to \(k\).
  For \(g(C) = 0\) the tangent space \(H^1(C,\mathcal O_C)\) vanishes, so
  \(\Pic^0_{C/k}\) is a smooth proper group scheme of dimension \(0\), namely
  \(\Spec k\); the universal property then asserts that every pointed morphism
  from \(C\) to an abelian variety is constant, which is the rigidity statement
  that a morphism from a genus-\(0\) curve to an abelian variety is constant.
  The third is the basepoint condition \(P \circ \iota_P = \eta\), a hypothesis
  of \cref{lem:pic0_isAlbanese_algClosed} rather than a restriction on it.
\end{proof}

\begin{lemma}[Albanese property over an algebraically closed field]
  \label{lem:pic0_isAlbanese_algClosed}
  \lean{AlgebraicGeometry.isAlbanese_pic0_of_isAlgClosed}
  \uses{def:IsAlbanese, thm:albanese_universal_property_northstar}
  Let \(C\) be a smooth proper geometrically integral curve over an
  algebraically closed field \(\bar k\), with representable Picard functor and
  genus \(g(C) > 0\), and let \(P \in C(\bar k)\) satisfy
  \(P \circ \iota_P = \eta\) for the Abel--Jacobi morphism \(\iota_P\) of
  \((C, P)\). Then \(\Pic^0_{C/\bar k}\) satisfies the Albanese universal
  property for the pointed curve \((C, P)\).
\end{lemma}

\begin{proof}\leanok
  \uses{thm:albanese_universal_property_northstar}
  The universal property of \cref{def:IsAlbanese} has two clauses. The basepoint
  clause is the hypothesis. The factorisation clause --- every pointed morphism
  \(\varphi : C \to A\) into an abelian variety factors uniquely through
  \(\iota_P\) --- is \cref{thm:albanese_universal_property_northstar} at the same
  object, the Albanese development's Jacobian scheme being \(\Pic^0_{C/\bar k}\).
\end{proof}

\begin{theorem}[Existence of a Jacobian witness]
  \label{thm:nonempty_jacobianWitness}
  \uses{def:JacobianWitness, def:picardJacobianWitness}
  \lean{AlgebraicGeometry.nonempty_jacobianWitness}
  Every smooth proper geometrically irreducible curve has a Jacobian witness.
\end{theorem}

\begin{proof}
  Take the witness on \(\Pic^0_{C/k}\) supplied by
  Theorem~\ref{def:picardJacobianWitness}.
\end{proof}

\begin{definition}[Chosen Jacobian witness]
  \label{def:jacobianWitness}
  \uses{def:JacobianWitness, thm:nonempty_jacobianWitness}
  \lean{AlgebraicGeometry.jacobianWitness}
  Fix one Jacobian witness for \(C\).
\end{definition}

