for f in sorted(glob.glob(os.path.join(root,'AlgebraicJacobian/**/*.lean'),recursive=True)):
    lines=open(f,encoding='utf-8').read().split('\n')
    cur=[]
    for i,line in enumerate(lines):
        m=re.match(r'^namespace\s+([\w.α-ωΓ]+)',line)
        if m: cur.append(m.group(1)); continue
        m=re.match(r'^end\s+([\w.α-ωΓ]+)',line)
        if m:
            if cur and cur[-1]==m.group(1): cur.pop()
            continue
        m=pat.match(line)
        if not m: continue
        nm=m.group(3)
        full=nm if m.group(2) else ('.'.join(cur+[nm]) if cur else nm)
        # body: until next boundary at col 0
        j=i+1
        while j<len(lines):
            if lines[j] and not lines[j][0].isspace() and boundary.match(lines[j]): break
            j+=1
        body='\n'.join(lines[i:j])
        names={full}
        for k in range(len(cur)+1):
            names.add('.'.join(cur[k:]+[nm]) if cur else nm)
        for n in names: declmap.setdefault(n,(f,i+1,body))
envs=('theorem','lemma','proposition','corollary','definition','remark','example','notation','convention','proof')
begin=re.compile(r'\\begin\{('+'|'.join(envs)+r')\}'); end=re.compile(r'\\end\{('+'|'.join(envs)+r')\}')
for fn in files:
    lines=open(os.path.join(chdir,fn),encoding='utf-8').read().split('\n')
    cur=None; blocks=[]
    for i,l in enumerate(lines,1):
        if l.lstrip().startswith('%'): continue
        m=begin.search(l)
        if m and cur is None: cur={'env':m.group(1),'start':i,'txt':[]}
        if cur is not None:
            cur['txt'].append(l)
            if end.search(l): blocks.append(cur); cur=None
    out=[]
    for b in blocks:
        t='\n'.join(b['txt'])
        if '\\leanok' not in t or '\\mathlibok' in t: continue
        names=[n.strip() for m in re.finditer(r'\\lean\{([^}]*)\}',t) for n in m.group(1).split(',') if n.strip()]
        lab=re.search(r'\\label\{([^}]*)\}',t); lab=lab.group(1) if lab else '?'
        for n in names:
            if n in declmap:
                f,ln,body=declmap[n]
                if re.search(r'(^|[\s(\[])sorry([\s)\]]|$)',body,re.M):
                    out.append('  L%-5d %-10s %-50s SORRY %s:%d (%s)'%(b['start'],b['env'],lab,os.path.relpath(f,root),ln,n))
    print('===',fn, len(out))
    for o in out: print(o)
